 static void run(String mode,double h)throws Exception{Model m=ModelUtil.load("m"+mode,BASE);MeshSequence q=m.component("comp1").mesh("mesh1");q.feature("size").set("custom","on");q.feature("size").set("hmax",h);q.feature("size").set("hmin",4.16e-5);q.feature("size").set("hgrad",1.3);q.feature("size").set("hcurve",.2);q.feature("size").set("hnarrow",1.0);q.run();try{m.result().dataset().remove("tm_ref");}catch(Exception e){}try{m.result().export().remove("tm_ref_data");}catch(Exception e){}m.result().dataset().create("tm_ref","CutPoint3D");m.result().dataset("tm_ref").set("pointx",new double[]{-.015});m.result().dataset("tm_ref").set("pointy",new double[]{0});m.result().dataset("tm_ref").set("pointz",new double[]{.0046});m.result().export().create("tm_ref_data","Data");m.result().export("tm_ref_data").set("data","tm_ref");m.result().export("tm_ref_data").set("expr",new String[]{"p"});m.param().set("src_state","2");m.study("std1").feature("step1").set("plist","range(1020,2,1280)");System.out.printf(Locale.US,"AUDIT %s hmax=%.4f elements=%d%n",mode,h,q.getNumElem());m.study("std1").run();m.result().export("tdata").set("filename",OUT+mode+"_center_src2.txt");m.result().export("tdata").run();m.result().export("tm_ref_data").set("filename",OUT+mode+"_westref_src2.txt");m.result().export("tm_ref_data").run();m.save(OUT+mode+"_src2.mph");ModelUtil.remove("m"+mode);}
 public static void main(String[] a)throws Exception{ModelUtil.initStandalone(true);run("F32",.0032);run("F26",.0026);run("F20",.0020);}
